  "concept_name": "Equations show mathematical balance",
  "explanation": "An equation is a statement that two expressions are equal. We use an equals sign (=) to show that the value on the left side is exactly the same as the value on the right side. This helps us explore relationships between numbers.",
  "key_idea": "An equation is a statement of equality that must always remain balanced.",
  "visual_hint": "balance_scale"
}
